in vec2 vUV;
in float vAlpha;
in float vIntensity;
in vec3 vColor;
in float vNormalizedAge; layout(location = 0) out vec4 FragColor;
layout(location = 1) out vec4 BrightColor; uniform sampler2D u_SmokeTexture;
uniform sampler2D u_NoiseTexture;
uniform bool u_ErosionEnabled;
uniform float u_ErosionScale;
uniform float u_ErosionEdgeWidth;
uniform vec3 u_ErosionEdgeColor; void main() { vec4 smokeTex = texture(u_SmokeTexture, vUV); vec3 finalColor = smokeTex.rgb * vColor; float finalAlpha = smokeTex.a * vAlpha; if (u_ErosionEnabled) { vec4 noiseTex = texture(u_NoiseTexture, vUV); float erosionThreshold = clamp(vNormalizedAge * u_ErosionScale, 0.0, 1.0); // Discard des fragments rongés par le bruit if (noiseTex.r < erosionThreshold) { discard; } // Couture incandescente d'érosion if (noiseTex.r < erosionThreshold + u_ErosionEdgeWidth) { float edgeFactor = (noiseTex.r - erosionThreshold) / max(0.0001, u_ErosionEdgeWidth); finalColor = mix(u_ErosionEdgeColor, finalColor, edgeFactor); finalAlpha = min(1.0, finalAlpha * 1.5); } } FragColor = vec4(finalColor * vIntensity, finalAlpha * vIntensity); BrightColor = vec4(0.0, 0.0, 0.0, 0.0);
